#[unsafe(no_mangle)]
pub unsafe extern "C" fn CreateSpinningBerrySprite(
    mut berryId: u8_0,
    mut x: u8_0,
    mut y: u8_0,
    mut startAffine: bool8,
) -> u8_0 {
    let mut spriteId: u8_0 = 0;
    FreeSpritePaletteByTag(30020 as u16_0);
    LoadBerryGfx(berryId);
    spriteId = CreateSprite(
        &raw const sBerryPicRotatingSpriteTemplate,
        x as s16,
        y as s16,
        0 as u8_0,
    );
    if startAffine as ::core::ffi::c_int == 1 as ::core::ffi::c_int {
        StartSpriteAffineAnim(
            (&raw mut gSprites as *mut Sprite).offset(spriteId as isize) as *mut Sprite,
            1 as u8_0,
        );
    }
    return spriteId;
}
